"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["70679"],{90293(e,t,a){a.r(t),a.d(t,{metadata:()=>n,default:()=>u,frontMatter:()=>c,contentTitle:()=>d,toc:()=>l,assets:()=>p});var n=JSON.parse('{"id":"nhcx/v1/api/onboarding/endpoints/onboarding-v2-participant-create","title":"Participant create (v2)","description":"Registry-linked creation: registry type and ID, role codes, endpoint URL and contacts; returns participantid and a transactionid for /validate.","source":"@site/docs/nhcx/v1/api/onboarding/endpoints/onboarding-v2-participant-create.mdx","sourceDirName":"nhcx/v1/api/onboarding/endpoints","slug":"/nhcx/v1/api/onboarding/endpoints/onboarding-v2-participant-create","permalink":"/docs/main/docs/nhcx/v1/api/onboarding/endpoints/onboarding-v2-participant-create","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Participant create (v2)","sidebar_label":"Participant create (v2)","sidebar_class_name":"api-method api-method--post","description":"Registry-linked creation: registry type and ID, role codes, endpoint URL and contacts; returns participantid and a transactionid for /validate.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","verification":"unverified","source":"nhcx-onboarding.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Participant create (v1)","permalink":"/docs/main/docs/nhcx/v1/api/onboarding/endpoints/onboarding-participant-create"},"next":{"title":"HEM-entity participant create","permalink":"/docs/main/docs/nhcx/v1/api/onboarding/endpoints/onboarding-v2-participant-hementity-create"}}'),i=a(62540),r=a(43023),s=a(44136),o=JSON.parse('{"id":"onboarding_v2_participant_create","module":"Onboarding","moduleId":"onboarding","kind":"operation","method":"POST","path":"/v2/participant/create","server":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","servers":[{"url":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","description":"Sandbox, Participant service."},{"url":"https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice","description":"Production."}],"summary":"Participant create (v2)","description":"Registry-linked creation: registry type and ID, role codes, endpoint URL and contacts; returns participantid and a transactionid for /validate.\\n\\n### Business purpose\\n\\nProduction onboarding needs to prove that the organisation registering on NHCX is the same one already known to an external authority (the ABDM Health Facility Registry for hospitals, the IRDAI registry for insurers and TPAs). The v2 create therefore takes a thin, registry-linked payload rather than a full profile, validates the mobile number against the number held in HFR or the NHCX payer details, and sends a one-time passcode to that number. This is step 1 of the four-step production sequence and is what turns a verified facility into an addressable NHCX participant.\\n\\n### When to use\\n\\nUse at production onboarding after sandbox certification has been reviewed and credentials issued; the documented URL is https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice/v2/participant/create. It is always followed by GET /validate with the returned transactionid and the SMS passcode, which must happen within 24 hours. In the sandbox the FAQ lists the unversioned /participant/create instead. No NHCX workflow codes or x-hcx-status values apply; this is a synchronous JSON call outside the JWE protocol.\\n\\n### Preconditions\\n\\n- Production (or sandbox) credentials and a fresh Bearer token in bearer_auth with the Bearer prefix; Accept and Content-Type set to application/json.\\n- registrytype from the Valid Registry Enums: HFR 10001, NIN 10002, ROHINI 10003, PAYER 10004 (HFR/EUA use 10001, PAYER/TPA use 10004).\\n- role as an array from the Valid Role Enums: PROVIDER 10001, PAYER 10002, AGENCY_TPA 10003, EUA 10009, among others.\\n- registryid formatted correctly: HFR ID for providers; IRDAI ID with leading zeros stripped for payers.\\n- mobilenumber already registered with HFR (providers) or NHCX payer details (payers); both must match for the call to succeed.\\n- Required fields: registrytype, registryid, role, endpointurl, mobilenumber, email; scheme_code is optional.\\n\\n### Postconditions\\n\\nHTTP 200 with ParticipantCreateV2Resp: participantid, facilityname, facilitycontact and facilityemail echoed from the linked registry, a transactionid such as 1vouv8tlz2tnl-1fpspjhwj07c6, and an error object (code, message, trace). A passcode is sent by SMS to the registered mobile number. The participant is not confirmed until GET /validate?transactionId=&passcode= succeeds; the transaction id and passcode are valid for 24 hours and each re-trigger generates a new pair. Only after creation confirmation can /v2/participant/update be used to upload the certificate and endpoint. Failures use the standard 400/404/500 ErrorResponse envelope.\\n\\n### Common mistakes\\n\\n- Confusing the two 10001 enums: 10001 is PROVIDER as a role and HFR/EUA as a registry type; they are different fields.\\n- Sending the IRDAI registry ID with leading zeros (0123 instead of 123), which the NHA lists as a frequent production failure.\\n- Using a mobile number that does not match the one on record in HFR or the NHCX payer details; the validation requires an exact match.\\n- Losing the transactionid: if it is forgotten, the only recovery is to create the request again, which issues a new passcode.\\n- Letting the 24-hour validity lapse before calling /validate.\\n- Sending the v1 snake_case body or expecting a participant_code key; this response uses participantid.\\n\\n### Best practices\\n\\n- Persist transactionid immediately, together with the timestamp, so the /validate step can be completed by whoever holds the registered phone.\\n- Verify the mobile number and registry ID against HFR or IRDAI records before calling; the check is strict and every failed attempt is a manual round trip.\\n- Treat the error object in a 200 response as meaningful and surface it to the operator rather than assuming success from the HTTP status alone.\\n- Do not retry blindly: each call generates a new transaction id and passcode and invalidates the plan to confirm the previous one.\\n- Keep sandbox and production credentials, hosts and participant codes strictly separate.\\n\\n### Related scenario\\n\\nAn insurer\'s TPA has cleared sandbox certification and received production credentials. Its integrator obtains a Bearer token, then calls /v2/participant/create with registrytype 10004, the IRDAI-issued registry ID (leading zeros stripped), role [\\"10003\\"], the production callback base URL and the mobile number the NHA has on file. The response returns participantid, the facility details and transactionid 1vouv8tlz2tnl-1fpspjhwj07c6, and an SMS passcode reaches the compliance officer\'s phone. Within the hour the team calls GET /validate with both values to confirm creation, then proceeds to /v2/participant/update to publish its encryption certificate.\\n\\n### Specification\\n\\nChapter [Your certificate](/docs/nhcx/v1/getting-started/your-certificate) of the NHCX integration specification.","security":[{"name":"bearerAuth","type":"http","scheme":"bearer","description":"On every NHCX call, the token goes in a header called `bearer_auth`, with the word `Bearer` and a space in front. The sources are not unanimous: the authentication page and the FAQ both write the example as `Authorization`, and the notification endpoint uses `Authorization`. The safe course, and what the adapter does, is to send both headers with the same value."}],"headers":[{"name":"bearer_auth","required":true,"description":"It is `bearer_auth`, not `Authorization`, on NHCX\'s own endpoints.","example":"Bearer <access token>","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"registrytype","type":"string","required":false,"description":"","encrypted":false},{"name":"registryid","type":"string","required":false,"description":"","encrypted":false},{"name":"role","type":"string[]","required":false,"description":"","encrypted":false},{"name":"endpointurl","type":"string","required":false,"description":"","encrypted":false},{"name":"mobilenumber","type":"string","required":false,"description":"","encrypted":false},{"name":"email","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"registrytype":"10001","registryid":"XXXXX74586","role":["10001"],"endpointurl":"https://nhcx.demohospital.example.in","mobilenumber":"XXXX748348","email":"sample@gmail.com"},"responses":[{"status":"200","description":"HTTP 200 with ParticipantCreateV2Resp: participantid, facilityname, facilitycontact and facilityemail echoed from the linked registry, a transactionid such as 1vouv8tlz2tnl-1fpspjhwj07c6, and an error object (code, message, trace).","example":{"participantid":"XXXXX7583@hcx","facilityname":"Demo Multispeciality Hospital","facilitycontact":"XXXX748348","facilityemail":"sample@gmail.com","transactionid":"1vouv8tlz2tnl-1fpspjhwj07c6","error":{"code":"","message":"","trace":""}}}],"tag":"Onboarding","tagDescription":"Nothing moves through NHCX until both the sender and the recipient exist in the participant registry, which the platform treats as the source of truth for who may exchange claims data.","curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/v2/participant/create \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"registrytype\\": \\"10001\\",\\n  \\"registryid\\": \\"XXXXX74586\\",\\n  \\"role\\": [\\n    \\"10001\\"\\n  ],\\n  \\"endpointurl\\": \\"https://nhcx.demohospital.example.in\\",\\n  \\"mobilenumber\\": \\"XXXX748348\\",\\n  \\"email\\": \\"sample@gmail.com\\"\\n}\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/v2/participant/create \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"registrytype\\": \\"10001\\",\\n  \\"registryid\\": \\"XXXXX74586\\",\\n  \\"role\\": [\\n    \\"10001\\"\\n  ],\\n  \\"endpointurl\\": \\"https://nhcx.demohospital.example.in\\",\\n  \\"mobilenumber\\": \\"XXXX748348\\",\\n  \\"email\\": \\"sample@gmail.com\\"\\n}\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.post(\\n    \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/v2/participant/create\\",\\n    headers={\\n        \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n        \\"bearer_auth\\": \\"Bearer <access token>\\",\\n        \\"Content-Type\\": \\"application/json\\",\\n    },\\n    json={\\n        \\"registrytype\\": \\"10001\\",\\n        \\"registryid\\": \\"XXXXX74586\\",\\n        \\"role\\": [\\n            \\"10001\\"\\n        ],\\n        \\"endpointurl\\": \\"https://nhcx.demohospital.example.in\\",\\n        \\"mobilenumber\\": \\"XXXX748348\\",\\n        \\"email\\": \\"sample@gmail.com\\"\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/v2/participant/create\\", {\\n  method: \\"POST\\",\\n  headers: {\\n    \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n    \\"bearer_auth\\": \\"Bearer <access token>\\",\\n    \\"Content-Type\\": \\"application/json\\",\\n  },\\n  body: JSON.stringify({\\n    \\"registrytype\\": \\"10001\\",\\n    \\"registryid\\": \\"XXXXX74586\\",\\n    \\"role\\": [\\n      \\"10001\\"\\n    ],\\n    \\"endpointurl\\": \\"https://nhcx.demohospital.example.in\\",\\n    \\"mobilenumber\\": \\"XXXX748348\\",\\n    \\"email\\": \\"sample@gmail.com\\"\\n  }),\\n});\\n\\nconsole.log(response.status, await response.text());"}]}');let c={title:"Participant create (v2)",sidebar_label:"Participant create (v2)",sidebar_class_name:"api-method api-method--post",description:"Registry-linked creation: registry type and ID, role codes, endpoint URL and contacts; returns participantid and a transactionid for /validate.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",verification:"unverified",source:"nhcx-onboarding.yaml",generated:!0},d,p={},l=[];function h(e){return(0,i.jsx)(s.A,{operation:o})}function u(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(h,{...e})}):h(e)}}}]);